<?php
namespace Apie\Faker\Support;

/**
 * Pre-encoded mono MPEG-2 Layer III (22.05 kHz, 64 kbps) sine tones of 0.2 seconds.
 * Every note is a self contained series of frames (no bit reservoir carry over), so they can be joined in any order.
 */
final class Mp3Notes
{
    /** @var list<string> Notes from C4 up to E5 in a major pentatonic scale. */
    public const BASE64 = [
        '',
        '',
        '',
        '',
        '',
        '',
    ];

    /** @return list<string> */
    public static function decode(): array
    {
        return array_map(base64_decode(...), self::BASE64);
    }
}
